-- ── the post-migration assertion (the 0084 model) ─────────────────────────
-- Made-up uuids. The accepted shapes are inserted first and rolled back by a
-- sentinel exception, so a CHECK that refused everything fails the
-- migration; each refused shape runs in its own subtransaction and must be
-- refused BY ITS NAMED CONSTRAINT (guide §3).
DO $$
DECLARE
	t uuid := gen_random_uuid();
	w uuid := gen_random_uuid();
	u uuid := gen_random_uuid();
	g uuid := gen_random_uuid();
	refused_by text;
	expected text;
	probe text;
BEGIN
	-- (1) accepted shapes: every status with what it needs (gated_out without
	-- an unload — a truck turned away; gated_out WITH a late unload), a hand
	-- delivery with no vehicle, a BH and a temporary plate, a typed and a
	-- partner transporter, every seal status, an undeclared count, every
	-- document kind, a document with a PO, one with an ASN, one with neither,
	-- and a receipt linked to the gate-in.
	BEGIN
		INSERT INTO "gate_ins" ("id","tenant_id","warehouse_id","code","status","hand_delivery","vehicle_no","container_no",
			"transporter_partner_id","transporter_snapshot","transporter_name","lr_number","driver_name","driver_phone",
			"seal_status","seal_number","packages_declared","packages_counted","dock_door","gated_in_at",
			"unload_started_at","unload_started_by","unload_ended_at","unload_ended_by","gated_out_at","gated_out_by","recorded_by")
		VALUES
			(g, t, w, 'GI-0001', 'gated_in', false, 'KA01AB1234', 'MSKU1234567', gen_random_uuid(), '{"v":1}'::jsonb, NULL, 'LR-1', 'Ravi', '9876543345',
			 'intact', 'S-991, C-12', 12, NULL, 'D3', now(), NULL, NULL, NULL, NULL, NULL, NULL, u),
			(gen_random_uuid(), t, w, 'GI-0002', 'unloading', true, NULL, NULL, NULL, NULL, 'Hand courier', NULL, NULL, '+919876543345',
			 'none', NULL, NULL, NULL, NULL, now(), now(), u, NULL, NULL, NULL, NULL, u),
			(gen_random_uuid(), t, w, 'GI-0003', 'unloaded', false, '22BH1234AA', NULL, NULL, NULL, 'VRL', NULL, NULL, NULL,
			 'broken', 'S-1', 0, 0, NULL, now(), now(), u, now(), u, NULL, NULL, u),
			(gen_random_uuid(), t, w, 'GI-0004', 'gated_out', false, 'T0822KA1234Z', NULL, NULL, NULL, 'VRL', NULL, NULL, NULL,
			 'none', NULL, NULL, NULL, NULL, now(), NULL, NULL, NULL, NULL, now(), u, u),
			(gen_random_uuid(), t, w, 'GI-0005', 'gated_out', false, 'MH12AB1234', NULL, NULL, NULL, 'VRL', NULL, NULL, NULL,
			 'intact', 'S-2', 1000000, 1000000, NULL, now(), now(), u, now(), u, now(), u, u);
		INSERT INTO "gate_in_documents" ("id","tenant_id","gate_in_id","position","kind","number","document_date","eway_bill_no","po_id","asn_id")
		VALUES
			(gen_random_uuid(), t, g, 0, 'invoice', 'INV-1', '2026-10-21', '123456789012', gen_random_uuid(), NULL),
			(gen_random_uuid(), t, g, 1, 'challan', 'DC-1', '2026-10-21', NULL, NULL, gen_random_uuid()),
			(gen_random_uuid(), t, g, 2, 'bill_of_entry', 'BOE 77', '2026-10-21', NULL, NULL, NULL);
		INSERT INTO "goods_receipt_notes" ("id","tenant_id","warehouse_id","code","po_id","blind_reason_code","gate_in_id","device_id","recorded_by","occurred_at","recorded_at")
		VALUES (gen_random_uuid(), t, w, 'GRN-PROBE', NULL, 'other', g, gen_random_uuid(), u, now(), now());
		INSERT INTO "audit_events" ("id","tenant_id","actor_user_id","action","target_type","target_id","reference","changes")
		VALUES (gen_random_uuid(), t, u, 'gate_in.amended', 'gate_in', g, 'probe', '{"sealStatus":{"before":"intact","after":"broken"}}'::jsonb);
		RAISE EXCEPTION USING ERRCODE = 'P0086', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR unique_violation OR not_null_violation THEN
			RAISE EXCEPTION 'migration 0086: an accepted shape was refused (%).', SQLERRM;
		WHEN SQLSTATE 'P0086' THEN
			NULL;
	END;
	-- (2) refused shapes, each by its named constraint.
	FOREACH probe IN ARRAY ARRAY[
		'status unknown', 'no vehicle', 'vehicle lower-case', 'vehicle 3 characters', 'vehicle with a space',
		'container 12', 'container lower-case', 'no transporter', 'both transporters', 'partner without snapshot',
		'snapshot without partner', 'transporter name 81', 'lr 31', 'driver name untrimmed', 'phone letters',
		'phone 6 digits', 'seal unknown', 'intact without seal', 'none with seal', 'seal 121', 'declared negative',
		'counted over', 'dock 21', 'start without actor', 'end without count', 'gate-out without actor',
		'unloading without start', 'unloaded without end', 'gated out without time', 'gated-out time while open',
		'end while unloading', 'start while gated in', 'duplicate code',
		'document kind unknown', 'document number blank', 'document number 41', 'ewb 11 digits', 'po and asn',
		'position negative', 'duplicate position'
	] LOOP
		refused_by := NULL;
		expected := CASE probe
			WHEN 'status unknown' THEN 'gate_ins_status_check'
			WHEN 'no vehicle' THEN 'gate_ins_vehicle_required'
			WHEN 'vehicle lower-case' THEN 'gate_ins_vehicle_no_format'
			WHEN 'vehicle 3 characters' THEN 'gate_ins_vehicle_no_format'
			WHEN 'vehicle with a space' THEN 'gate_ins_vehicle_no_format'
			WHEN 'container 12' THEN 'gate_ins_container_no_format'
			WHEN 'container lower-case' THEN 'gate_ins_container_no_format'
			WHEN 'no transporter' THEN 'gate_ins_transporter_one'
			WHEN 'both transporters' THEN 'gate_ins_transporter_one'
			WHEN 'partner without snapshot' THEN 'gate_ins_transporter_one'
			WHEN 'snapshot without partner' THEN 'gate_ins_transporter_one'
			WHEN 'transporter name 81' THEN 'gate_ins_transporter_name_length'
			WHEN 'lr 31' THEN 'gate_ins_lr_number_length'
			WHEN 'driver name untrimmed' THEN 'gate_ins_driver_name_length'
			WHEN 'phone letters' THEN 'gate_ins_driver_phone_format'
			WHEN 'phone 6 digits' THEN 'gate_ins_driver_phone_format'
			WHEN 'seal unknown' THEN 'gate_ins_seal_status_check'
			WHEN 'intact without seal' THEN 'gate_ins_seal_number_pairing'
			WHEN 'none with seal' THEN 'gate_ins_seal_number_pairing'
			WHEN 'seal 121' THEN 'gate_ins_seal_number_pairing'
			WHEN 'declared negative' THEN 'gate_ins_packages_declared_range'
			WHEN 'counted over' THEN 'gate_ins_packages_counted_range'
			WHEN 'dock 21' THEN 'gate_ins_dock_door_length'
			WHEN 'start without actor' THEN 'gate_ins_unload_start_pairing'
			WHEN 'end without count' THEN 'gate_ins_unload_end_pairing'
			WHEN 'gate-out without actor' THEN 'gate_ins_gate_out_pairing'
			WHEN 'unloading without start' THEN 'gate_ins_status_unloading'
			WHEN 'unloaded without end' THEN 'gate_ins_status_unloaded'
			WHEN 'gated out without time' THEN 'gate_ins_status_gated_out'
			WHEN 'gated-out time while open' THEN 'gate_ins_gated_out_status'
			WHEN 'end while unloading' THEN 'gate_ins_unload_end_status'
			WHEN 'start while gated in' THEN 'gate_ins_unload_start_status'
			WHEN 'duplicate code' THEN 'gate_ins_tenant_code_unique'
			WHEN 'document kind unknown' THEN 'gate_in_documents_kind_check'
			WHEN 'document number blank' THEN 'gate_in_documents_number_length'
			WHEN 'document number 41' THEN 'gate_in_documents_number_length'
			WHEN 'ewb 11 digits' THEN 'gate_in_documents_eway_bill_format'
			WHEN 'po and asn' THEN 'gate_in_documents_one_document'
			WHEN 'position negative' THEN 'gate_in_documents_position_range'
			ELSE 'gate_in_documents_tenant_gate_in_position_unique'
		END;
		BEGIN
			CASE probe
				WHEN 'status unknown' THEN
					INSERT INTO "gate_ins" ("id","tenant_id","warehouse_id","code","status","vehicle_no","transporter_name","seal_status","gated_in_at","recorded_by")
					VALUES (gen_random_uuid(), t, w, 'GI-9001', 'parked', 'KA01AB1234', 'VRL', 'none', now(), u);
				WHEN 'no vehicle' THEN
					INSERT INTO "gate_ins" ("id","tenant_id","warehouse_id","code","hand_delivery","vehicle_no","transporter_name","seal_status","gated_in_at","recorded_by")
					VALUES (gen_random_uuid(), t, w, 'GI-9002', false, NULL, 'VRL', 'none', now(), u);
				WHEN 'vehicle lower-case' THEN
					INSERT INTO "gate_ins" ("id","tenant_id","warehouse_id","code","vehicle_no","transporter_name","seal_status","gated_in_at","recorded_by")
					VALUES (gen_random_uuid(), t, w, 'GI-9003', 'ka01ab1234', 'VRL', 'none', now(), u);
				WHEN 'vehicle 3 characters' THEN
					INSERT INTO "gate_ins" ("id","tenant_id","warehouse_id","code","vehicle_no","transporter_name","seal_status","gated_in_at","recorded_by")
					VALUES (gen_random_uuid(), t, w, 'GI-9004', 'KA1', 'VRL', 'none', now(), u);
				WHEN 'vehicle with a space' THEN
					INSERT INTO "gate_ins" ("id","tenant_id","warehouse_id","code","vehicle_no","transporter_name","seal_status","gated_in_at","recorded_by")
					VALUES (gen_random_uuid(), t, w, 'GI-9005', 'KA01 AB1234', 'VRL', 'none', now(), u);
				WHEN 'container 12' THEN
					INSERT INTO "gate_ins" ("id","tenant_id","warehouse_id","code","vehicle_no","container_no","transporter_name","seal_status","gated_in_at","recorded_by")
					VALUES (gen_random_uuid(), t, w, 'GI-9006', 'KA01AB1234', 'MSKU12345678', 'VRL', 'none', now(), u);
				WHEN 'container lower-case' THEN
					INSERT INTO "gate_ins" ("id","tenant_id","warehouse_id","code","vehicle_no","container_no","transporter_name","seal_status","gated_in_at","recorded_by")
					VALUES (gen_random_uuid(), t, w, 'GI-9007', 'KA01AB1234', 'msku1234567', 'VRL', 'none', now(), u);
				WHEN 'no transporter' THEN
					INSERT INTO "gate_ins" ("id","tenant_id","warehouse_id","code","vehicle_no","seal_status","gated_in_at","recorded_by")
					VALUES (gen_random_uuid(), t, w, 'GI-9008', 'KA01AB1234', 'none', now(), u);
				WHEN 'both transporters' THEN
					INSERT INTO "gate_ins" ("id","tenant_id","warehouse_id","code","vehicle_no","transporter_partner_id","transporter_snapshot","transporter_name","seal_status","gated_in_at","recorded_by")
					VALUES (gen_random_uuid(), t, w, 'GI-9009', 'KA01AB1234', gen_random_uuid(), '{"v":1}'::jsonb, 'VRL', 'none', now(), u);
				WHEN 'partner without snapshot' THEN
					INSERT INTO "gate_ins" ("id","tenant_id","warehouse_id","code","vehicle_no","transporter_partner_id","seal_status","gated_in_at","recorded_by")
					VALUES (gen_random_uuid(), t, w, 'GI-9010', 'KA01AB1234', gen_random_uuid(), 'none', now(), u);
				WHEN 'snapshot without partner' THEN
					INSERT INTO "gate_ins" ("id","tenant_id","warehouse_id","code","vehicle_no","transporter_snapshot","transporter_name","seal_status","gated_in_at","recorded_by")
					VALUES (gen_random_uuid(), t, w, 'GI-9011', 'KA01AB1234', '{"v":1}'::jsonb, 'VRL', 'none', now(), u);
				WHEN 'transporter name 81' THEN
					INSERT INTO "gate_ins" ("id","tenant_id","warehouse_id","code","vehicle_no","transporter_name","seal_status","gated_in_at","recorded_by")
					VALUES (gen_random_uuid(), t, w, 'GI-9012', 'KA01AB1234', repeat('T', 81), 'none', now(), u);
				WHEN 'lr 31' THEN
					INSERT INTO "gate_ins" ("id","tenant_id","warehouse_id","code","vehicle_no","transporter_name","lr_number","seal_status","gated_in_at","recorded_by")
					VALUES (gen_random_uuid(), t, w, 'GI-9013', 'KA01AB1234', 'VRL', repeat('L', 31), 'none', now(), u);
				WHEN 'driver name untrimmed' THEN
