				WHEN 'phone letters' THEN
					INSERT INTO "gate_ins" ("id","tenant_id","warehouse_id","code","vehicle_no","transporter_name","driver_phone","seal_status","gated_in_at","recorded_by")
					VALUES (gen_random_uuid(), t, w, 'GI-9015', 'KA01AB1234', 'VRL', 'abc', 'none', now(), u);
				WHEN 'phone 6 digits' THEN
					INSERT INTO "gate_ins" ("id","tenant_id","warehouse_id","code","vehicle_no","transporter_name","driver_phone","seal_status","gated_in_at","recorded_by")
					VALUES (gen_random_uuid(), t, w, 'GI-9016', 'KA01AB1234', 'VRL', '987654', 'none', now(), u);
				WHEN 'seal unknown' THEN
					INSERT INTO "gate_ins" ("id","tenant_id","warehouse_id","code","vehicle_no","transporter_name","seal_status","seal_number","gated_in_at","recorded_by")
					VALUES (gen_random_uuid(), t, w, 'GI-9017', 'KA01AB1234', 'VRL', 'tampered', 'S-1', now(), u);
				WHEN 'intact without seal' THEN
					INSERT INTO "gate_ins" ("id","tenant_id","warehouse_id","code","vehicle_no","transporter_name","seal_status","gated_in_at","recorded_by")
					VALUES (gen_random_uuid(), t, w, 'GI-9018', 'KA01AB1234', 'VRL', 'intact', now(), u);
				WHEN 'none with seal' THEN
					INSERT INTO "gate_ins" ("id","tenant_id","warehouse_id","code","vehicle_no","transporter_name","seal_status","seal_number","gated_in_at","recorded_by")
					VALUES (gen_random_uuid(), t, w, 'GI-9019', 'KA01AB1234', 'VRL', 'none', 'S-1', now(), u);
				WHEN 'seal 121' THEN
					INSERT INTO "gate_ins" ("id","tenant_id","warehouse_id","code","vehicle_no","transporter_name","seal_status","seal_number","gated_in_at","recorded_by")
					VALUES (gen_random_uuid(), t, w, 'GI-9020', 'KA01AB1234', 'VRL', 'broken', repeat('S', 121), now(), u);
				WHEN 'declared negative' THEN
					INSERT INTO "gate_ins" ("id","tenant_id","warehouse_id","code","vehicle_no","transporter_name","seal_status","packages_declared","gated_in_at","recorded_by")
					VALUES (gen_random_uuid(), t, w, 'GI-9021', 'KA01AB1234', 'VRL', 'none', -1, now(), u);
				WHEN 'counted over' THEN
					INSERT INTO "gate_ins" ("id","tenant_id","warehouse_id","code","status","vehicle_no","transporter_name","seal_status","packages_counted","gated_in_at",
						"unload_started_at","unload_started_by","unload_ended_at","unload_ended_by","recorded_by")
					VALUES (gen_random_uuid(), t, w, 'GI-9022', 'unloaded', 'KA01AB1234', 'VRL', 'none', 1000001, now(), now(), u, now(), u, u);
				WHEN 'dock 21' THEN
					INSERT INTO "gate_ins" ("id","tenant_id","warehouse_id","code","vehicle_no","transporter_name","seal_status","dock_door","gated_in_at","recorded_by")
					VALUES (gen_random_uuid(), t, w, 'GI-9023', 'KA01AB1234', 'VRL', 'none', repeat('D', 21), now(), u);
				WHEN 'start without actor' THEN
					INSERT INTO "gate_ins" ("id","tenant_id","warehouse_id","code","status","vehicle_no","transporter_name","seal_status","gated_in_at","unload_started_at","recorded_by")
					VALUES (gen_random_uuid(), t, w, 'GI-9024', 'unloading', 'KA01AB1234', 'VRL', 'none', now(), now(), u);
				WHEN 'end without count' THEN
					INSERT INTO "gate_ins" ("id","tenant_id","warehouse_id","code","status","vehicle_no","transporter_name","seal_status","gated_in_at",
						"unload_started_at","unload_started_by","unload_ended_at","unload_ended_by","gated_out_at","gated_out_by","recorded_by")
					VALUES (gen_random_uuid(), t, w, 'GI-9025', 'gated_out', 'KA01AB1234', 'VRL', 'none', now(), now(), u, now(), u, now(), u, u);
				WHEN 'gate-out without actor' THEN
					INSERT INTO "gate_ins" ("id","tenant_id","warehouse_id","code","vehicle_no","transporter_name","seal_status","gated_in_at","gated_out_at","recorded_by")
					VALUES (gen_random_uuid(), t, w, 'GI-9026', 'KA01AB1234', 'VRL', 'none', now(), now(), u);
				WHEN 'unloading without start' THEN
					INSERT INTO "gate_ins" ("id","tenant_id","warehouse_id","code","status","vehicle_no","transporter_name","seal_status","gated_in_at","recorded_by")
					VALUES (gen_random_uuid(), t, w, 'GI-9027', 'unloading', 'KA01AB1234', 'VRL', 'none', now(), u);
				WHEN 'unloaded without end' THEN
					INSERT INTO "gate_ins" ("id","tenant_id","warehouse_id","code","status","vehicle_no","transporter_name","seal_status","gated_in_at","unload_started_at","unload_started_by","recorded_by")
					VALUES (gen_random_uuid(), t, w, 'GI-9028', 'unloaded', 'KA01AB1234', 'VRL', 'none', now(), now(), u, u);
				WHEN 'gated out without time' THEN
					INSERT INTO "gate_ins" ("id","tenant_id","warehouse_id","code","status","vehicle_no","transporter_name","seal_status","gated_in_at","recorded_by")
					VALUES (gen_random_uuid(), t, w, 'GI-9029', 'gated_out', 'KA01AB1234', 'VRL', 'none', now(), u);
				WHEN 'gated-out time while open' THEN
					INSERT INTO "gate_ins" ("id","tenant_id","warehouse_id","code","status","vehicle_no","transporter_name","seal_status","packages_counted","gated_in_at",
						"unload_started_at","unload_started_by","unload_ended_at","unload_ended_by","gated_out_at","gated_out_by","recorded_by")
					VALUES (gen_random_uuid(), t, w, 'GI-9031', 'unloaded', 'KA01AB1234', 'VRL', 'none', 1, now(), now(), u, now(), u, now(), u, u);
				WHEN 'end while unloading' THEN
					INSERT INTO "gate_ins" ("id","tenant_id","warehouse_id","code","status","vehicle_no","transporter_name","seal_status","packages_counted","gated_in_at",
						"unload_started_at","unload_started_by","unload_ended_at","unload_ended_by","recorded_by")
					VALUES (gen_random_uuid(), t, w, 'GI-9032', 'unloading', 'KA01AB1234', 'VRL', 'none', 1, now(), now(), u, now(), u, u);
				WHEN 'start while gated in' THEN
					INSERT INTO "gate_ins" ("id","tenant_id","warehouse_id","code","status","vehicle_no","transporter_name","seal_status","gated_in_at","unload_started_at","unload_started_by","recorded_by")
					VALUES (gen_random_uuid(), t, w, 'GI-9033', 'gated_in', 'KA01AB1234', 'VRL', 'none', now(), now(), u, u);
				WHEN 'duplicate code' THEN
					INSERT INTO "gate_ins" ("id","tenant_id","warehouse_id","code","vehicle_no","transporter_name","seal_status","gated_in_at","recorded_by")
					VALUES (gen_random_uuid(), t, w, 'GI-9030', 'KA01AB1234', 'VRL', 'none', now(), u),
					       (gen_random_uuid(), t, w, 'GI-9030', 'KA01AB1235', 'VRL', 'none', now(), u);
				WHEN 'document kind unknown' THEN
					INSERT INTO "gate_in_documents" ("id","tenant_id","gate_in_id","position","kind","number","document_date")
					VALUES (gen_random_uuid(), t, g, 0, 'packing_list', 'PL-1', '2026-10-21');
				WHEN 'document number blank' THEN
					INSERT INTO "gate_in_documents" ("id","tenant_id","gate_in_id","position","kind","number","document_date")
					VALUES (gen_random_uuid(), t, g, 0, 'invoice', '', '2026-10-21');
				WHEN 'document number 41' THEN
					INSERT INTO "gate_in_documents" ("id","tenant_id","gate_in_id","position","kind","number","document_date")
					VALUES (gen_random_uuid(), t, g, 0, 'invoice', repeat('9', 41), '2026-10-21');
				WHEN 'ewb 11 digits' THEN
					INSERT INTO "gate_in_documents" ("id","tenant_id","gate_in_id","position","kind","number","document_date","eway_bill_no")
					VALUES (gen_random_uuid(), t, g, 0, 'invoice', 'INV-2', '2026-10-21', '12345678901');
				WHEN 'po and asn' THEN
					INSERT INTO "gate_in_documents" ("id","tenant_id","gate_in_id","position","kind","number","document_date","po_id","asn_id")
					VALUES (gen_random_uuid(), t, g, 0, 'invoice', 'INV-3', '2026-10-21', gen_random_uuid(), gen_random_uuid());
				WHEN 'position negative' THEN
					INSERT INTO "gate_in_documents" ("id","tenant_id","gate_in_id","position","kind","number","document_date")
					VALUES (gen_random_uuid(), t, g, -1, 'invoice', 'INV-4', '2026-10-21');
				WHEN 'duplicate position' THEN
					INSERT INTO "gate_in_documents" ("id","tenant_id","gate_in_id","position","kind","number","document_date")
					VALUES (gen_random_uuid(), t, g, 3, 'invoice', 'INV-5', '2026-10-21'),
					       (gen_random_uuid(), t, g, 3, 'challan', 'DC-5', '2026-10-21');
			END CASE;
		EXCEPTION
			WHEN check_violation OR unique_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		END;
		IF refused_by IS DISTINCT FROM expected THEN
			RAISE EXCEPTION 'migration 0086: probe "%" was refused by % (expected %).', probe, coalesce(refused_by, 'nothing'), expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "gate_ins" WHERE "tenant_id" = t) OR EXISTS (SELECT 1 FROM "gate_in_documents" WHERE "tenant_id" = t)
	   OR EXISTS (SELECT 1 FROM "goods_receipt_notes" WHERE "tenant_id" = t) OR EXISTS (SELECT 1 FROM "audit_events" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0086: a probe row survived.';
	END IF;
END $$;
